const j = $json;
const from = (j.from && j.from.value && j.from.value[0]) || {};
const to = ((j.to && j.to.value) || []).map(function (x) { return x.address; });
const MAX_FILE = 3 * 1024 * 1024; // the app's host caps a request at about 4.5 MB
const attachments = [];
const bin = $input.item.binary || {};
for (const key of Object.keys(bin)) {
  const b = bin[key];
  const entry = { filename: b.fileName || key, content_type: b.mimeType || 'application/octet-stream', size: Number(b.fileSize) || 0 };
  if (Number(b.fileSize) > 0 && Number(b.fileSize) <= MAX_FILE) {
    const buf = await this.helpers.getBinaryDataBuffer($itemIndex, key);
    entry.size = buf.length;
    entry.content_base64 = buf.toString('base64');
  }
  attachments.push(entry);
}
return {
  json: {
    app_url: j.app_url,
    payload: {
      provider_message_id: j.id,
      provider_thread_id: j.threadId || null,
      from: from.name ? from.name + ' <' + from.address + '>' : from.address,
      to: to,
      subject: j.subject || '(no subject)',
      received_at: new Date(j.date).toISOString(),
      body_text: j.text || '',
      body_html: j.html || null,
      attachments: attachments
    }
  }
};
